export const getPublicActivityContext = <ThrowOnError extends boolean = false>(options: Options<GetPublicActivityContextData, ThrowOnError>): RequestResult<GetPublicActivityContextResponses, GetPublicActivityContextErrors, ThrowOnError> => (options.client ?? client).get<GetPublicActivityContextResponses, GetPublicActivityContextErrors, ThrowOnError>({ url: '/catalog/resources/{courseId}/versions/{courseVersionId}/activities/{activityId}/versions/{activityVersionId}', ...options });
